import { useState } from "react";
import { useResults } from "../context/ResultsContext";

export default function UploadResumes() {
  const [files, setFiles] = useState([]);
  const [githubLinks, setGithubLinks] = useState([]);
  const { setResults } = useResults();

  const submit = async () => {
    const formData = new FormData();

    files.forEach((f) => formData.append("resumes", f));
    githubLinks.forEach((g) => formData.append("github_links", g));

    const res = await fetch("http://localhost:5000/api/analyze", {
      method: "POST",
      body: formData,
    });

    const data = await res.json();
    setResults(data.results);
  };

  return (
    <div className="card p-4 shadow">
      <h2>Upload Resumes</h2>

      <input
        type="file"
        multiple
        accept=".pdf,.docx"
        className="form-control mt-3"
        onChange={(e) => setFiles([...e.target.files])}
      />

      {files.map((_, i) => (
        <input
          key={i}
          type="text"
          placeholder="GitHub / Portfolio link (optional)"
          className="form-control mt-2"
          onChange={(e) => {
            const copy = [...githubLinks];
            copy[i] = e.target.value;
            setGithubLinks(copy);
          }}
        />
      ))}

      <button className="btn btn-primary mt-3" onClick={submit}>
        Analyze Resumes
      </button>
    </div>
  );
}
